import * as React from "react"
// Leaflet's stylesheet is a plain CSS import: webpack handles it at build time
// and it never touches `window`, so it is safe in the SSR bundle. Only the
// library itself has to wait for the browser.
import "leaflet/dist/leaflet.css"
import { sortedCounties } from "../../lib/service-area-geo"
import * as s from "./ServiceAreaMap.module.css"

/**
 * The county picker, as a map. Ported from contractor.wiki, recoloured to the
 * FCS blue and rewritten against this project's CSS Modules.
 *
 * ── THE POLYGONS ARE THE MAP ───────────────────────────────────────────────
 * There is no tile layer by default. The Census boundaries are the thing being
 * clicked, and drawing them on a white ground makes the counties easier to
 * read than a street map competing underneath. Street tiles are an explicit
 * opt-in, because OpenStreetMap's public tile servers are donated
 * infrastructure, not unlimited commercial hosting — silently pulling tiles
 * for every contractor editing a service area would be abusing them.
 *
 * ── THIS IS NOT THE ONLY WAY TO SELECT ─────────────────────────────────────
 * A Leaflet polygon is not a focusable control and cannot be reached with a
 * keyboard. A map-only selector would lock out every keyboard and screen
 * reader user, so the map is deliberately one of TWO views of the same
 * selection — the checkbox list beside it is the accessible one, and neither
 * is a second source of truth.
 *
 * ── LEAFLET IS LOADED ON DEMAND ────────────────────────────────────────────
 * Leaflet reads `window` at import time, which would break Gatsby's static
 * render outright. Importing it inside an effect keeps it out of the SSR
 * bundle, and keeps ~150 KB off the initial download for everyone who never
 * reaches this step.
 */

const UNSELECTED = { color: "#94a3b8", weight: 1, fillColor: "#ffffff", fillOpacity: 1 }
const SELECTED = { color: "#0d3f8f", weight: 1.5, fillColor: "#1668e8", fillOpacity: 0.55 }
const HOVER = { weight: 2.5, color: "#0d3f8f" }

/**
 * `lockedFips` — MTC-FCS-026. A whole state is covered by one tick, so its
 * counties are drawn selected and stop responding to clicks: toggling one off
 * individually would be a change with nothing to show for it. A LIST now
 * rather than a single boolean, because whole-state and county-by-county
 * states sit on the same map.
 */
const ServiceAreaMap = ({ data, selected, onToggle, lockedFips = [], stateName }) => {
  const container = React.useRef(null)
  const mapRef = React.useRef(null)
  const layerRef = React.useRef(null)

  // Handlers registered on a Leaflet layer close over the values present when
  // the layer was built. Reading through refs keeps a click made ten
  // selections later from writing a stale array back.
  const selectedRef = React.useRef(selected)
  const toggleRef = React.useRef(onToggle)
  const lockedRef = React.useRef(lockedFips)
  selectedRef.current = selected
  toggleRef.current = onToggle
  lockedRef.current = lockedFips

  const isLocked = geoid => lockedRef.current.includes(String(geoid).slice(0, 2))

  const [tiles, setTiles] = React.useState(false)
  const [ready, setReady] = React.useState(false)
  const [failed, setFailed] = React.useState(false)

  /* ── Build the map once the geography arrives ───────────────────────── */
  React.useEffect(() => {
    if (!container.current || !data) return undefined
    let cancelled = false
    let map = null

    import("leaflet")
      .then(mod => {
        const L = mod.default || mod
        if (cancelled || !container.current) return

        map = L.map(container.current, {
          // A map that swallows the page scroll inside a long form is hostile.
          // Zoom is by control or pinch, never by scrolling past it.
          scrollWheelZoom: false,
          zoomControl: true,
          attributionControl: true,
          // Whole-number zoom makes fitBounds pick the largest level that
          // fits, which for a wide state leaves the map at half the size of
          // its container. Fractional zoom lets it actually fill the frame.
          zoomSnap: 0,
        })
        mapRef.current = map

        const layer = L.geoJSON(data, {
          style: feature =>
            selectedRef.current.includes(feature.properties.GEOID) ? SELECTED : UNSELECTED,
          onEachFeature: (feature, lyr) => {
            const props = feature.properties
            lyr.bindTooltip(props.NAMELSAD, { sticky: true })
            lyr.on({
              click: () => {
                if (isLocked(props.GEOID)) return
                toggleRef.current(props.GEOID)
              },
              mouseover: () => {
                if (isLocked(props.GEOID)) return
                lyr.setStyle(HOVER)
              },
              mouseout: () => layer.resetStyle(lyr),
            })
          },
        })

        layer.addTo(map)
        layerRef.current = layer

        // The container is sized by CSS that may not have settled when the
        // map was constructed; Leaflet caches that size and would fit the
        // bounds to the wrong rectangle.
        map.invalidateSize()

        const bounds = layer.getBounds()
        if (bounds.isValid()) map.fitBounds(bounds, { padding: [12, 12] })

        // Census attribution belongs on the map itself, not only in prose
        // below it, because the map is the thing derived from their data.
        map.attributionControl.addAttribution(
          'Boundaries: <a href="https://www.census.gov/geographies/mapping-files/time-series/geo/cartographic-boundary.html">US Census Bureau</a>'
        )

        setReady(true)
      })
      .catch(() => {
        if (!cancelled) setFailed(true)
      })

    return () => {
      cancelled = true
      if (map) map.remove()
      mapRef.current = null
      layerRef.current = null
      setReady(false)
    }
  }, [data])

  /* ── Repaint when the selection changes ─────────────────────────────── */
  React.useEffect(() => {
    const layer = layerRef.current
    if (!layer) return
    layer.setStyle(feature =>
      selected.includes(feature.properties.GEOID) ? SELECTED : UNSELECTED
    )
  }, [selected, ready])

  /* ── Street tiles, only when asked for ──────────────────────────────── */
  React.useEffect(() => {
    const map = mapRef.current
    if (!map || !ready || !tiles) return undefined
    let cancelled = false
    let added = null

    import("leaflet").then(mod => {
      if (cancelled || !mapRef.current) return
      const L = mod.default || mod
      const t = L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png", {
        maxZoom: 18,
        attribution:
          '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
      })
      t.addTo(mapRef.current)
      // Under the counties, not over them — the counties are the control.
      t.bringToBack()
      added = t
    })

    return () => {
      cancelled = true
      if (added) added.remove()
    }
  }, [tiles, ready])

  if (failed) {
    return (
      <p className={s.failed}>
        The map could not be loaded. You can still choose counties from the list — it selects
        exactly the same areas.
      </p>
    )
  }

  return (
    <div>
      <div className={s.frame}>
        <div
          ref={container}
          className={s.canvas}
          // The map duplicates the checkbox list, which is the accessible path
          // through this control. Announcing an unreachable canvas of 3,000
          // unlabelled shapes helps nobody.
          aria-hidden="true"
        />

        {!ready && (
          <div className={s.overlay}>
            <p>Loading {stateName} counties…</p>
          </div>
        )}

      </div>

      <div className={s.meta}>
        <label className={s.tiles}>
          <input type="checkbox" checked={tiles} onChange={e => setTiles(e.target.checked)} />
          Show street map underneath
        </label>
        <p>County boundaries from the US Census Bureau. Generalised for mapping.</p>
      </div>
    </div>
  )
}

export { sortedCounties }
export default ServiceAreaMap
