import * as React from "react"
import { templateById } from "../../data/site-templates"
import { tierById } from "../../data/plans"
import { formatMoney } from "../../config/pricing"
import * as s from "./PriceToast.module.css"

/**
 * What this design would have cost — MTC-FCS-052.
 * ============================================================================
 * Slides up from the bottom of the full screen preview when it opens, and
 * again every time the contractor flips to another design, with the figure
 * moved to match. That timing is the whole point: the moment somebody is
 * admiring a page is the moment the price is worth saying.
 *
 * ── WHAT IT IS ALLOWED TO CLAIM ────────────────────────────────────────────
 * The struck-through figure is `worth` from data/site-templates.js — what a
 * designer would charge to build the page. It is a comparison, and it is
 * written as one. It is never presented as a price of ours that has been
 * reduced, because no such price ever existed, and "was $800, now free" about
 * a thing we have never sold is simply untrue.
 *
 * The rest is the real arithmetic: nothing to pay today, and the monthly
 * hosting for whichever tier that design needs. A free design on the free
 * tier costs nothing at all and says so, rather than inventing a number to
 * keep the layout symmetrical.
 */

const PriceToast = ({ templateId, plan }) => {
  const template = templateById(templateId)

  /* A premium design needs a paid tier. If they are already on one, that is
     the price they will pay — quoting Premium at somebody who has chosen Lead
     Generation would understate their own bill. */
  const tier = tierById(plan)
  const needsPaid = Boolean(template.premium)
  const billed = needsPaid ? (tier.amount > 0 ? tier : tierById("premium")) : tierById(plan)

  /* Re-enter the animation on every change. Without the key the element is
     the same one React already drew and the CSS animation does not replay, so
     the second design would change the numbers with no movement at all. */
  const [shownFor, setShownFor] = React.useState(templateId)
  const [visible, setVisible] = React.useState(true)

  React.useEffect(() => {
    setShownFor(templateId)
    setVisible(true)
    // Long enough to read twice, short enough not to sit over the footer of
    // the page somebody came here to look at.
    const timer = window.setTimeout(() => setVisible(false), 6000)
    return () => window.clearTimeout(timer)
  }, [templateId])

  if (!visible) return null

  const monthly = billed.amount > 0 ? `${formatMoney(billed.amount)}/month` : "free"

  /* formatMoney drops the decimals on a round number, which is right for
     "$800" beside a design and wrong for the figure being paid today: "$0"
     reads as an absence, "$0.00" reads as a price. */
  const today = formatMoney(0).includes(".") ? formatMoney(0) : `${formatMoney(0)}.00`

  return (
    <div className={s.toast} key={shownFor} role="status" aria-live="polite">
      <div className={s.left}>
        <p className={s.kicker}>{template.label}</p>
        <p className={s.was}>
          <span className={s.wasLabel}>Built by a designer</span>
          <s className={s.wasPrice}>{formatMoney(template.worth || 80000)}</s>
        </p>
      </div>

      <div className={s.now}>
        <p className={s.nowPrice}>
          {today}
          {billed.amount > 0 ? <span className={s.plus}> + {monthly}</span> : null}
        </p>
        <p className={s.nowNote}>
          {billed.amount > 0 ? "Just pay hosting — cancel any time" : "No charge at all"}
        </p>
      </div>
    </div>
  )
}

export default PriceToast
