import * as React from "react"
import Header from "../components/Header"
import Seo from "../components/Seo"
import StepTrade from "../components/builder/StepTrade"
import StepServices from "../components/builder/StepServices"
import StepDetails from "../components/builder/StepDetails"
import StepAreas from "../components/builder/StepAreas"
import StepCustomise from "../components/builder/StepCustomise"
import StepCheckout from "../components/builder/StepCheckout"
import { emptyDraft, furthestStep, generateDraft, loadDraft, saveDraft } from "../lib/site-draft"
import { handoffMode, readHandoff, seedDraft } from "../lib/builder-handoff"
import * as s from "../components/builder/Builder.module.css"

/**
 * THE WEBSITE BUILDER — MTC-FCS-002.
 * ============================================================================
 * Get started → trade → services → words → service area → generate → make it
 * yours → go live → Stripe.
 *
 * ── ONE PAGE, NOT SEVEN ROUTES ─────────────────────────────────────────────
 * Every step is state on this page. Routing each one would put the draft
 * through a full page load per answer, and the first refresh in the middle of
 * it would lose everything the contractor typed. It also means Back is
 * instant, which matters when somebody is comparing two services.
 *
 * ── THE DRAFT SURVIVES A CLOSED TAB ────────────────────────────────────────
 * Persisted to localStorage on every change. This flow is eight screens and
 * people get interrupted; coming back to a half-built site is the difference
 * between finishing and starting again. It stays in the browser — it holds a
 * business's contact details and nothing is posted anywhere until they choose
 * to go live.
 *
 * ── GENERATING IS DELIBERATELY VISIBLE ─────────────────────────────────────
 * The work itself is instant. The short pause exists because a site that
 * appears the same frame the button is pressed reads as a template swap, and
 * the three lines name what was actually built from their answers. It plays
 * ONCE: somebody returning to change their service area is correcting a site
 * they have already met, and two more seconds of theatre is a tax on that.
 *
 * ── ANY ANSWER CAN BE CHANGED, AT ANY POINT ────────────────────────────────
 * The step trail under the progress bar is navigable in both directions, as
 * far as `furthestStep` says the answers justify. A wizard that only moves
 * forward makes a typo on screen three a reason to start again, and the
 * previous-step button underneath is no help when the thing you want to fix
 * is three screens back. Nothing is recomputed by visiting a step, so leaving
 * and returning costs nothing.
 */

const STEPS = [
  { id: "trade", label: "Your trade", Component: StepTrade },
  { id: "services", label: "Your services", Component: StepServices },
  { id: "details", label: "Your details", Component: StepDetails },
  { id: "areas", label: "Service area", Component: StepAreas },
  { id: "customise", label: "Your website", Component: StepCustomise },
  { id: "checkout", label: "Go live", Component: StepCheckout },
]

const GENERATING_LINES = [
  "Laying out your home page…",
  "Writing your service descriptions…",
  "Adding your service area…",
]

const BuilderPage = ({ location }) => {
  const [draft, setDraft] = React.useState(emptyDraft)
  const [index, setIndex] = React.useState(0)
  const [hydrated, setHydrated] = React.useState(false)
  const [generating, setGenerating] = React.useState(false)
  const [line, setLine] = React.useState(0)
  // What a squeeze page asked for, and what we did about it.
  const [handoff, setHandoff] = React.useState(null)
  const [mode, setMode] = React.useState("none")

  // Restore before the first paint the visitor can interact with, but never
  // during SSR — localStorage does not exist there.
  React.useEffect(() => {
    const saved = loadDraft()
    const incoming = readHandoff(location?.search)
    const decision = handoffMode(incoming, saved)

    setHandoff(incoming)
    setMode(decision)

    if (decision === "seed") {
      // Arrived from a trade landing page with nothing to lose. Open on the
      // SERVICES step rather than the first question: the trade is already
      // answered, and starting there shows them what was chosen instead of
      // hiding it behind a step they never saw.
      setDraft(seedDraft(incoming))
      setIndex(1)
      setHydrated(true)
      return
    }

    if (saved) {
      setDraft(saved)
      // Somebody returning to a generated draft wants the site, not question
      // one. Anything earlier resumes where the answers ran out.
      if (saved.generated) setIndex(4)
      else if ((saved.areas.states || []).length > 0) setIndex(3)
      else if (saved.services.length > 0) setIndex(2)
      else if (saved.tradeSlug) setIndex(1)
    }
    setHydrated(true)
  }, [location])

  /** Discards the draft in progress and starts again for the incoming trade. */
  const restartForHandoff = () => {
    setDraft(seedDraft(handoff))
    setIndex(1)
    setMode("seed")
  }

  React.useEffect(() => {
    if (hydrated) saveDraft(draft)
  }, [draft, hydrated])

  // Each step is a fresh screen, so start it at the top rather than halfway
  // down where the last one was scrolled to.
  React.useEffect(() => {
    if (hydrated) window.scrollTo({ top: 0, behavior: "smooth" })
  }, [index, hydrated])

  React.useEffect(() => {
    if (!generating) return undefined
    const tick = setInterval(() => setLine(n => n + 1), 620)
    const done = setTimeout(() => {
      setDraft(current => generateDraft(current))
      setGenerating(false)
      setLine(0)
      setIndex(4)
    }, 2000)
    return () => {
      clearInterval(tick)
      clearTimeout(done)
    }
  }, [generating])

  const update = patch => setDraft(current => ({ ...current, ...patch }))

  const next = () => {
    // Leaving the service-area step is what "Generate my website" means.
    if (STEPS[index].id === "areas") {
      if (draft.generated) {
        // Built once already. generateDraft only fills what is still empty,
        // so this picks up a newly chosen service without touching a single
        // thing they have customised — and skips the animation, which has
        // nothing left to announce.
        setDraft(current => generateDraft(current))
        setIndex(4)
        return
      }
      setGenerating(true)
      return
    }
    setIndex(n => Math.min(n + 1, STEPS.length - 1))
  }

  const back = () => setIndex(n => Math.max(n - 1, 0))

  // How far the trail opens. `index` is in the max because the checkout step
  // is reached by asking for it, not by answering anything.
  const furthest = Math.max(furthestStep(draft), index)

  /** Jump straight to a step — MTC-FCS-012. Refuses anything not yet earned. */
  const goTo = target => {
    if (target === index || target < 0 || target > furthest) return
    setIndex(target)
  }

  const step = STEPS[index]
  const Step = step.Component

  return (
    <>
      <Header />
      <main className={s.page} data-print="hide">
        <div className={`container ${s.wide}`}>
          {generating ? (
            <div className={s.generating}>
              <span className={s.spinner} />
              <h1 className={s.question} style={{ marginBottom: 4 }}>
                Building your website
              </h1>
              <div className={s.generatingSteps}>
                {GENERATING_LINES.map((text, i) => (
                  <p key={text} className={i <= line ? s.generatingOn : ""}>
                    {text}
                  </p>
                ))}
              </div>
            </div>
          ) : (
            <>
              <div className={s.progress}>
                <div className={s.progressHead}>
                  <span className={s.progressStep}>
                    Step {index + 1} of {STEPS.length}
                  </span>
                  <span className={s.progressLabel}>{step.label}</span>
                </div>
                <div
                  className={s.progressTrack}
                  role="progressbar"
                  aria-valuenow={index + 1}
                  aria-valuemin={1}
                  aria-valuemax={STEPS.length}
                  aria-label="Builder progress"
                >
                  <div
                    className={s.progressBar}
                    style={{ width: `${((index + 1) / STEPS.length) * 100}%` }}
                  />
                </div>

                {/* Both directions: a step already earned stays open, so going
                    back to fix a typo does not cost the walk forward again.
                    Steps not yet earned are plain text, not disabled buttons —
                    a button that refuses to do anything is worse than a label
                    that never offered. */}
                <ol className={s.trail}>
                  {STEPS.map((item, i) => {
                    const current = i === index
                    const open = !current && i <= furthest
                    const tone = current ? s.stepOn : i <= furthest ? s.stepDone : s.stepAhead
                    return (
                      <li key={item.id}>
                        {open ? (
                          <button
                            type="button"
                            className={`${s.step} ${tone}`}
                            onClick={() => goTo(i)}
                          >
                            <span className={s.stepNum}>{i + 1}</span>
                            <span className={s.stepLabel}>{item.label}</span>
                          </button>
                        ) : (
                          <span
                            className={`${s.step} ${tone}`}
                            aria-current={current ? "step" : undefined}
                          >
                            <span className={s.stepNum}>{i + 1}</span>
                            <span className={s.stepLabel}>{item.label}</span>
                          </span>
                        )}
                      </li>
                    )
                  })}
                </ol>
              </div>

              {mode === "seed" && index <= 2 && handoff?.trade ? (
                <p className={s.handoff}>
                  Set up for <strong>{handoff.trade.name.toLowerCase()}</strong>. Change anything
                  you like — nothing here is fixed.
                </p>
              ) : null}

              {mode === "offer" && handoff?.trade ? (
                <div className={s.handoffOffer}>
                  <span>
                    You already have a website in progress. We have left it alone — or start
                    again set up for {handoff.trade.name.toLowerCase()}.
                  </span>
                  <button type="button" onClick={restartForHandoff}>
                    Start again for {handoff.trade.name.toLowerCase()}
                  </button>
                </div>
              ) : null}

              <Step draft={draft} update={update} next={next} back={back} goTo={goTo} />
            </>
          )}
        </div>
      </main>
    </>
  )
}

export const Head = () => (
  <Seo
    title="Build your free website"
    description="Answer four questions and get a professional contracting website — free to build, you only pay for hosting."
  />
)

export default BuilderPage
