import { emptyDraft } from "./site-draft"
import { formatPhone } from "./phone"
import { tradeBySlug } from "../data/trades"
import { stateByCode } from "../data/us-states"

/**
 * ARRIVING FROM A SQUEEZE PAGE — MTC-FCS-006.
 * ============================================================================
 * The trade landing pages (roofer / painter / exteriors .contractor.wiki) send
 * contractors here with what they already know: which trade, which services,
 * and whatever the lead form captured. The builder opens already set up for
 * that trade — and every one of those answers stays editable, because a page
 * that arrives pre-filled and locked is worse than one that arrives blank.
 *
 * ── THE URL IS UNTRUSTED INPUT ─────────────────────────────────────────────
 * Anyone can type these parameters. Nothing here is taken on faith: the trade
 * must exist in our taxonomy, services are capped and length-limited, and every
 * string is trimmed and truncated before it can reach a draft that later gets
 * rendered into a published page.
 *
 * ── IT NEVER CLOBBERS WORK IN PROGRESS ─────────────────────────────────────
 * Someone who half-built a plumbing site and then clicks a roofing ad must not
 * lose it. `handoffMode` reports "seed" only for an untouched draft; an
 * existing one is left alone and the page offers to start again instead. Doing
 * it silently either way is the bad outcome — one destroys their work, the
 * other breaks the promise the ad made.
 */

/** Everything the squeeze pages may pass, and nothing else. */
const FIELDS = ["trade", "services", "business", "email", "phone", "city", "state", "from"]

const clean = (value, max) => String(value == null ? "" : value).trim().slice(0, max)

/**
 * Reads the handoff out of a location, or null when there isn't one.
 * Returns only values that survived validation.
 */
export function readHandoff(search) {
  if (!search) return null
  const params = new URLSearchParams(search)
  if (!FIELDS.some(f => params.has(f))) return null

  const trade = tradeBySlug(clean(params.get("trade"), 40).toLowerCase())

  const services = clean(params.get("services"), 200)
    .split(",")
    .map(s => s.trim().slice(0, 48))
    .filter(Boolean)
    // Three is what the builder and the generated site render. A link asking
    // for ten is a link that would silently lose seven.
    .slice(0, 3)

  return {
    trade: trade || null,
    services,
    business: clean(params.get("business"), 60),
    email: clean(params.get("email"), 90),
    phone: clean(params.get("phone"), 24),
    city: clean(params.get("city"), 60),
    state: clean(params.get("state"), 2).toUpperCase(),
    from: clean(params.get("from"), 40),
  }
}

/**
 * Whether a draft already in this browser counts as work in progress.
 *
 * A trade on its own is the first real answer, so anything past that is worth
 * protecting. An empty draft is not.
 */
export function draftHasWork(draft) {
  if (!draft) return false
  return Boolean(
    draft.tradeSlug ||
      draft.services.length > 0 ||
      draft.business.name.trim() ||
      draft.generated
  )
}

/**
 * What to do with a handoff, given whatever draft already exists.
 *
 *   "seed"    nothing to lose — set it up for the trade
 *   "offer"   they have work under way; keep it and offer to start again
 *   "none"    no handoff in the URL
 */
export function handoffMode(handoff, existing) {
  if (!handoff || !handoff.trade) return "none"
  if (!draftHasWork(existing)) return "seed"
  // Already building for this exact trade: nothing to offer, nothing to warn
  // about. Their draft is the handoff.
  if (existing.tradeSlug === handoff.trade.slug) return "none"
  return "offer"
}

/** Builds the starting draft. Services the trade does not list are kept. */
export function seedDraft(handoff) {
  const draft = emptyDraft()
  if (!handoff || !handoff.trade) return draft

  draft.tradeSlug = handoff.trade.slug
  draft.services = handoff.services
  draft.business = {
    ...draft.business,
    name: handoff.business,
    email: handoff.email,
    // A lead form on another site takes whatever somebody typed; the builder
    // shows it in the house format from the first screen. MTC-FCS-011.
    phone: formatPhone(handoff.phone),
  }
  // The lead form asks for a state, which is the first half of the service
  // area question. Counties still have to be chosen.
  const state = handoff.state ? stateByCode(handoff.state) : null
  // One state to begin with; the area step lets them add more — MTC-FCS-026.
  if (state) draft.areas = { ...draft.areas, states: [state.code], focus: state.code }
  return draft
}
