import * as React from "react"
import { apiUrl } from "../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../config/supabase-public"
import { slugProblem } from "./slug"

/**
 * Whether the address somebody is typing is free — FCS-059.
 * ============================================================================
 * Returns one of five states, because the honest answer while somebody types
 * is usually not yes or no:
 *
 *   idle       nothing typed yet
 *   invalid    the shape is wrong; said immediately, with no request
 *   checking   asked, waiting
 *   available  free
 *   taken      somebody has it
 *   unknown    we could not reach the check — NEVER treated as free
 *
 * ── WAITING IS THE WHOLE DESIGN ────────────────────────────────────────────
 * A request per keystroke would ask about `r`, `ri`, `rid`… and the answers
 * come back out of order, so the field ends up showing the verdict for a
 * prefix the person stopped typing half a second ago. So: settle for 450ms,
 * and abort the previous request when a newer one starts. The abort is what
 * keeps the LAST answer the one on screen.
 *
 * ── "WE COULD NOT CHECK" IS NOT "YES" ──────────────────────────────────────
 * If the check fails, this says so rather than falling through to available.
 * The cost of guessing wrong is somebody paying for an address that is
 * already somebody else's website.
 */

const SETTLE_MS = 450

export function useSubdomain(slug) {
  const [state, setState] = React.useState({ status: "idle", reason: "" })

  React.useEffect(() => {
    const value = String(slug || "").trim()

    if (!value) {
      setState({ status: "idle", reason: "" })
      return undefined
    }

    /* The shape is decided here, with no request: a name that cannot be an
       address does not need a round trip to be refused, and the answer is
       instant instead of half a second late. */
    const shape = slugProblem(value)
    if (shape) {
      setState({ status: "invalid", reason: shape })
      return undefined
    }

    setState({ status: "checking", reason: "" })

    const controller = new AbortController()
    const timer = window.setTimeout(async () => {
      try {
        const res = await fetch(apiUrl("subdomain-available"), {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            apikey: SUPABASE_PUBLISHABLE_KEY,
            Authorization: `Bearer ${SUPABASE_PUBLISHABLE_KEY}`,
          },
          body: JSON.stringify({ slug: value }),
          signal: controller.signal,
        })
        const body = await res.json()

        if (body.available === true) {
          setState({ status: "available", reason: "" })
        } else if (body.available === false) {
          setState({ status: "taken", reason: body.reason || "That address is already taken." })
        } else {
          setState({ status: "unknown", reason: body.reason || "We could not check that address." })
        }
      } catch (err) {
        // An abort is this hook replacing its own answer, not a failure.
        if (err.name === "AbortError") return
        setState({ status: "unknown", reason: "We could not check that address just now." })
      }
    }, SETTLE_MS)

    return () => {
      window.clearTimeout(timer)
      controller.abort()
    }
  }, [slug])

  return state
}
