import * as React from "react"
import { withPrefix } from "gatsby"
import { GALLERY, GALLERY_CATEGORIES, galleryFor } from "../../data/stock-gallery"
import { readImageFile } from "../../lib/read-image"
import * as s from "./Builder.module.css"

/**
 * Choosing a picture — MTC-FCS-027.
 * ============================================================================
 * Opens over everything when a picture is clicked, in the preview or in the
 * list. Three ways in, because people arrive with the image in three different
 * places: a file on the machine, a file already under the cursor, or nothing
 * at all and a need for something that will do.
 *
 * ── DROP ANYWHERE, NOT ON A 40px TARGET ────────────────────────────────────
 * The whole panel is the drop zone. A drop target the size of a button is a
 * target people miss, and a miss drops the image onto the page — which in a
 * browser means navigating away from the builder to view it.
 *
 * ── NOTHING IS UPLOADED ────────────────────────────────────────────────────
 * A chosen file is read in the browser, redrawn through a canvas to a sane
 * size and kept on the draft. It never leaves this machine until the site is
 * published, which is also why there is nothing here to promise about it.
 *
 * ── THE GALLERY IS ILLUSTRATIVE, AND SAYS SO ───────────────────────────────
 * These are stock photographs. They are fine behind a heading and wrong as a
 * portfolio, so the panel says so in as many words — and the premium "gallery
 * of your own work" section deliberately has no stock option at all.
 */
const ImagePicker = ({ slot, label, current, onChoose, onClear, onClose }) => {
  const [tab, setTab] = React.useState("upload")
  const [category, setCategory] = React.useState("all")
  const [dragging, setDragging] = React.useState(false)
  const [error, setError] = React.useState("")
  const [busy, setBusy] = React.useState(false)

  const images = galleryFor(category)

  React.useEffect(() => {
    const onKey = e => {
      if (e.key === "Escape") onClose()
    }
    const previous = document.body.style.overflow
    document.body.style.overflow = "hidden"
    window.addEventListener("keydown", onKey)
    return () => {
      document.body.style.overflow = previous
      window.removeEventListener("keydown", onKey)
    }
  }, [onClose])

  const take = async file => {
    setError("")
    if (!file) return
    setBusy(true)
    try {
      const dataUrl = await readImageFile(file)
      onChoose(dataUrl)
      onClose()
    } catch (err) {
      setError(err.message)
      setBusy(false)
    }
  }

  /**
   * A gallery picture goes through exactly the same reader as an upload.
   *
   * Two reasons, both of which bit:
   *
   *   1. `FileReader` takes the MIME type from the BLOB, and a host that does
   *      not know `.avif` serves `application/octet-stream`. A data URL with
   *      that type does not render in an `<img>` at all — and it would have
   *      worked on a host that knows AVIF and failed on one that does not,
   *      which is the worst way for this to break.
   *   2. AVIF is right for the picker's grid and wrong for a page somebody
   *      else hosts: Safari only learned it in 16.4. Re-encoding through the
   *      canvas gives the published page a JPEG every browser can draw.
   *
   * It also means the draft holds the picture itself. A published page that
   * pointed back at freecontractorservices.com for its photographs would
   * break the moment somebody hosted it somewhere else.
   */
  const takeFromGallery = async item => {
    setError("")
    setBusy(true)
    try {
      const res = await fetch(withPrefix(`/gallery/${item.file}`))
      if (!res.ok) throw new Error("That picture could not be loaded. Please try another.")
      const blob = await res.blob()
      // The type is asserted from the file we asked for, not taken from the
      // response — see above.
      const file = new File([blob], item.file, { type: "image/avif" })
      const dataUrl = await readImageFile(file)
      onChoose(dataUrl)
      onClose()
    } catch (err) {
      setError(
        err && err.message
          ? err.message
          : "That picture could not be used. Please try another."
      )
      setBusy(false)
    }
  }

  return (
    <div
      className={s.pickerWrap}
      role="dialog"
      aria-modal="true"
      aria-label={`Choose a picture for ${label}`}
      onDragOver={e => {
        e.preventDefault()
        setDragging(true)
      }}
      onDragLeave={e => {
        if (e.currentTarget === e.target) setDragging(false)
      }}
      onDrop={e => {
        e.preventDefault()
        setDragging(false)
        take(e.dataTransfer.files && e.dataTransfer.files[0])
      }}
    >
      <div className={s.pickerBar}>
        <span className={s.pickerTitle}>{label}</span>

        <div className={s.pickerTabs} role="tablist" aria-label="Where from">
          {[
            { id: "upload", label: "Upload" },
            { id: "gallery", label: "Pick from gallery" },
          ].map(t => (
            <button
              key={t.id}
              type="button"
              role="tab"
              aria-selected={tab === t.id}
              className={`${s.pickerTab} ${tab === t.id ? s.pickerTabOn : ""}`}
              onClick={() => setTab(t.id)}
            >
              {t.label}
            </button>
          ))}
        </div>

        <button type="button" className={s.pickerClose} onClick={onClose}>
          Close
        </button>
      </div>

      <div className={s.pickerBody}>
        {tab === "upload" ? (
          <div className={`${s.dropZone} ${dragging ? s.dropZoneOn : ""}`}>
            <p className={s.dropTitle}>
              {dragging ? "Let go to use this picture" : "Drag a picture in"}
            </p>
            <p className={s.dropNote}>
              …or choose one from this device. JPG, PNG or WEBP. Large photographs are resized
              automatically.
            </p>
            <label className={`btn btn--lg ${s.dropBtn}`}>
              {busy ? "Reading…" : "Choose a file"}
              <input
                type="file"
                accept="image/*"
                hidden
                onChange={e => {
                  const file = e.target.files && e.target.files[0]
                  take(file)
                  e.target.value = ""
                }}
              />
            </label>

            {current ? (
              <button
                type="button"
                className={s.dropClear}
                onClick={() => {
                  onClear()
                  onClose()
                }}
              >
                Remove the picture that is there now
              </button>
            ) : null}

            {error ? <p className={s.pickerError}>{error}</p> : null}
            <p className={s.pickerPrivacy}>
              Read in this browser. Nothing is uploaded until you put your site online.
            </p>
          </div>
        ) : (
          <div className={s.galleryPane}>
            <div className={s.galleryHead}>
              <label htmlFor="gallery-cat" className={s.galleryLabel}>
                Show
              </label>
              <select
                id="gallery-cat"
                className={s.select}
                value={category}
                onChange={e => setCategory(e.target.value)}
              >
                {GALLERY_CATEGORIES.map(c => (
                  <option key={c.id} value={c.id}>
                    {c.label}
                  </option>
                ))}
              </select>
              <p className={s.galleryNote}>
                Stock photographs — fine behind a heading, not a substitute for pictures of your
                own work.
              </p>
            </div>

            {images.length === 0 ? (
              <p className={s.galleryEmpty}>
                {GALLERY.length === 0
                  ? "The gallery is empty on this build. Run npm run gallery to fill it."
                  : "Nothing in that category yet — try “All”."}
              </p>
            ) : (
              <div className={s.galleryGrid}>
                {images.map(item => (
                  <button
                    key={item.id}
                    type="button"
                    className={s.galleryPick}
                    disabled={busy}
                    onClick={() => takeFromGallery(item)}
                  >
                    <img
                      src={withPrefix(`/gallery/${item.thumb}`)}
                      alt={item.label}
                      loading="lazy"
                    />
                    <span>{item.label}</span>
                  </button>
                ))}
              </div>
            )}

            {error ? <p className={s.pickerError}>{error}</p> : null}
          </div>
        )}
      </div>
    </div>
  )
}

export default ImagePicker
