import * as React from "react"
import { DAYS, LIMITS, PREMIUM_SECTIONS } from "../../data/premium"
import { readImageFile } from "../../lib/read-image"
import * as s from "./Builder.module.css"

/**
 * The Premium option boxes — MTC-FCS-015.
 * ============================================================================
 * Four extra sections a contractor can add to their site, each one a box with
 * a switch and, when it is on, the fields that fill it.
 *
 * ── SWITCHING A SECTION OFF DOES NOT DELETE WHAT IS IN IT ──────────────────
 * Toggling is how people compare two versions of a page, and a switch that
 * quietly destroys six typed-out reviews the first time somebody flicks it is
 * a trap. Off means "not rendered" — `activeExtras` in site-draft.js decides
 * that — and the content waits where it was left. The same applies to moving
 * back to Freemium.
 *
 * ── AN EMPTY SECTION IS NEVER PUBLISHED ────────────────────────────────────
 * Switching "Customer reviews" on and typing nothing renders nothing at all.
 * A heading sitting over a blank space reads as broken, which is worse for
 * the business than the section simply not being there.
 *
 * ── NOTHING HERE IS PRE-FILLED ─────────────────────────────────────────────
 * No starter reviews, no guessed opening hours, no sample questions. Reviews
 * in particular are the one thing on a contractor's site a customer is
 * entitled to assume is real, and a placeholder that survives to publication
 * is indistinguishable from a lie.
 */

/** One box: a title, a switch, and whatever the section needs when it is on. */
const Box = ({ section, on, onToggle, children }) => (
  <div className={`${s.panel} ${on ? s.premiumOn : ""}`}>
    <div className={s.premiumHead}>
      <span>
        <span className={s.premiumName}>{section.label}</span>
        <span className={s.premiumBlurb}>{section.blurb}</span>
      </span>
      <button
        type="button"
        role="switch"
        aria-checked={on}
        aria-label={`${on ? "Remove" : "Add"} ${section.label.toLowerCase()}`}
        className={`${s.toggle} ${on ? s.toggleOn : ""}`}
        onClick={onToggle}
      >
        <span className={s.toggleKnob} />
      </button>
    </div>
    {on ? <div className={s.premiumBody}>{children}</div> : null}
  </div>
)

const PremiumPanels = ({ draft, update, onError }) => {
  const extras = draft.extras || {}
  const byId = id => PREMIUM_SECTIONS.find(section => section.id === id)

  const toggle = id => {
    const on = !extras[id]
    const patch = { extras: { ...extras, [id]: on } }

    // Seeded only on the way ON, and only when there is nothing there — so a
    // section switched off and back on comes back exactly as it was left.
    if (on) {
      if (id === "hours" && (draft.hours || []).length === 0) {
        patch.hours = DAYS.map(day => ({ day, text: "" }))
      }
      if (id === "reviews" && (draft.reviews || []).length === 0) {
        patch.reviews = [{ name: "", quote: "" }]
      }
      if (id === "faqs" && (draft.faqs || []).length === 0) {
        patch.faqs = [{ q: "", a: "" }]
      }
    }
    update(patch)
  }

  const setRow = (key, i, field, value) => {
    const rows = [...(draft[key] || [])]
    rows[i] = { ...rows[i], [field]: value }
    update({ [key]: rows })
  }

  const addRow = (key, blank) => {
    const rows = [...(draft[key] || [])]
    if (rows.length >= (LIMITS[key] || 6)) return
    update({ [key]: [...rows, blank] })
  }

  const removeRow = (key, i) => {
    const rows = (draft[key] || []).filter((_, n) => n !== i)
    update({ [key]: rows })
  }

  const addPhoto = async file => {
    const gallery = draft.gallery || []
    if (gallery.length >= LIMITS.gallery) return
    try {
      const dataUrl = await readImageFile(file)
      update({ gallery: [...gallery, dataUrl] })
    } catch (err) {
      onError(err.message)
    }
  }

  const gallery = draft.gallery || []
  const reviews = draft.reviews || []
  const faqs = draft.faqs || []
  const hours = draft.hours || []

  return (
    <>
      <Box section={byId("gallery")} on={Boolean(extras.gallery)} onToggle={() => toggle("gallery")}>
        <div className={s.galleryStrip}>
          {gallery.map((src, i) => (
            <span key={i} className={s.galleryThumb}>
              <img src={src} alt="" />
              <button
                type="button"
                aria-label={`Remove photograph ${i + 1}`}
                onClick={() => update({ gallery: gallery.filter((_, n) => n !== i) })}
              >
                ×
              </button>
            </span>
          ))}
          {gallery.length < LIMITS.gallery ? (
            <label className={s.galleryAdd}>
              + Photo
              <input
                type="file"
                accept="image/*"
                hidden
                onChange={e => {
                  const file = e.target.files && e.target.files[0]
                  if (file) addPhoto(file)
                  // Cleared so choosing the same file twice still fires.
                  e.target.value = ""
                }}
              />
            </label>
          ) : null}
        </div>
        <p className={s.fieldNote}>
          Your own photographs only — up to {LIMITS.gallery}. {gallery.length} added.
        </p>
      </Box>

      <Box section={byId("reviews")} on={Boolean(extras.reviews)} onToggle={() => toggle("reviews")}>
        {reviews.map((review, i) => (
          <div key={i} className={s.premiumRow}>
            <textarea
              rows={2}
              value={review.quote}
              placeholder="What the customer said"
              maxLength={300}
              onChange={e => setRow("reviews", i, "quote", e.target.value)}
            />
            <div className={s.premiumRowFoot}>
              <input
                value={review.name}
                placeholder="Their name"
                maxLength={60}
                onChange={e => setRow("reviews", i, "name", e.target.value)}
              />
              <button type="button" className={s.linkBtn} onClick={() => removeRow("reviews", i)}>
                Remove
              </button>
            </div>
          </div>
        ))}
        {reviews.length < LIMITS.reviews ? (
          <button
            type="button"
            className={s.linkBtn}
            onClick={() => addRow("reviews", { name: "", quote: "" })}
          >
            + Add a review
          </button>
        ) : null}
        <p className={s.fieldNote}>
          Only quote customers who agreed to be quoted. Nothing here is written for you.
        </p>
      </Box>

      <Box section={byId("faqs")} on={Boolean(extras.faqs)} onToggle={() => toggle("faqs")}>
        {faqs.map((faq, i) => (
          <div key={i} className={s.premiumRow}>
            <input
              value={faq.q}
              placeholder="Do you give free estimates?"
              maxLength={140}
              onChange={e => setRow("faqs", i, "q", e.target.value)}
            />
            <textarea
              rows={2}
              value={faq.a}
              placeholder="Your answer"
              maxLength={400}
              onChange={e => setRow("faqs", i, "a", e.target.value)}
            />
            <div className={s.premiumRowFoot}>
              <button type="button" className={s.linkBtn} onClick={() => removeRow("faqs", i)}>
                Remove
              </button>
            </div>
          </div>
        ))}
        {faqs.length < LIMITS.faqs ? (
          <button
            type="button"
            className={s.linkBtn}
            onClick={() => addRow("faqs", { q: "", a: "" })}
          >
            + Add a question
          </button>
        ) : null}
        <p className={s.fieldNote}>A question with no answer is left off the page.</p>
      </Box>

      <Box section={byId("hours")} on={Boolean(extras.hours)} onToggle={() => toggle("hours")}>
        <div className={s.hoursGrid}>
          {hours.map((row, i) => (
            <label key={row.day} className={s.hoursField}>
              <span>{row.day}</span>
              <input
                value={row.text}
                placeholder="8am – 5pm, or Closed"
                maxLength={40}
                onChange={e => setRow("hours", i, "text", e.target.value)}
              />
            </label>
          ))}
        </div>
        <p className={s.fieldNote}>Days you leave blank are not shown.</p>
      </Box>
    </>
  )
}

export default PremiumPanels
