import * as React from "react"
import DevicePreview, { CANVAS } from "./DevicePreview"
import { THEMES, IMAGE_SLOTS, benefitPatch, benefitState, draftGaps } from "../../lib/site-draft"
import PremiumPanels from "./PremiumPanels"
import TemplatePicker from "./TemplatePicker"
import ImagePicker from "./ImagePicker"
import { PLANS, formatMoney } from "../../config/pricing"
import { LEVELS as LEVELS_ALL, TIER_ORDER } from "../../data/plans"
import PlanBenefits from "./PlanBenefits"
import { downloadSite } from "../../lib/site-export"
import { ArrowRight } from "../Icons"
import * as s from "./Builder.module.css"

/**
 * The site, generated — and the two things they are allowed to change here.
 *
 * ── THE PREVIEW IS THE SITE ────────────────────────────────────────────────
 * The frame is handed the exact HTML file the download and the publish
 * produce, rendered in an iframe at a real device width so the site's own
 * media queries fire. The phone tab is therefore a phone render, not a
 * squashed desktop — and if the export breaks, this looks broken.
 *
 * ── COLOURS AND PICTURES, NOT LAYOUT ───────────────────────────────────────
 * Six themes and five image slots. A full layout editor at this point in the
 * funnel is how a five-minute signup becomes an abandoned afternoon; the
 * things that make the site look like THEIR business are the colour and the
 * photographs, and those are what is on offer.
 *
 * ── THE FOOTER FOLLOWS THEM DOWN ───────────────────────────────────────────
 * "Go live now" is sticky, because the preview is long and a call to action
 * that scrolls off the top is a call to action nobody sees. It carries the
 * price of whichever plan is selected, so nobody reaches the checkout to find
 * out what this costs.
 *
 * ── FREEMIUM / PREMIUM — MTC-FCS-015 ───────────────────────────────────────
 * Premium adds four more sections, and choosing it here changes the preview
 * immediately: the point of a paid tier on this screen is to SHOW what it
 * does rather than describe it. Switching back to Freemium takes the sections
 * off the page and leaves everything typed into them alone, because the
 * switch is also how somebody compares the two.
 */
const StepCustomise = ({ draft, update, next, goTo }) => {
  const [device, setDevice] = React.useState("desktop")
  const [error, setError] = React.useState("")
  // Which picture the full-screen picker is open for — MTC-FCS-027.
  const [picking, setPicking] = React.useState(null)

  const gaps = draftGaps(draft)
  const plan = PLANS[draft.plan] ? draft.plan : "free"
  const chosenPlan = PLANS[plan]
  const benefits = benefitState(draft)

  // The tabs and the checkboxes are the same state from two directions, so
  // both write through here rather than each keeping their own idea of it.
  const setPlan = (nextPlan, nextBenefits) =>
    update({ plan: nextPlan, ...benefitPatch(draft, nextBenefits || benefits) })

  /** A tab press ticks everything in the tier it selects. */
  const chooseTier = nextPlan => {
    const next = {}
    const wanted = PLANS[nextPlan].levels
    for (const level of LEVELS_ALL) {
      const inTier = wanted.includes(level.id)
      for (const item of level.items) next[item.id] = inTier
    }
    setPlan(nextPlan, next)
  }

  // Every gap but one lives on the details screen; "Service area" lives on
  // the map. Sending them to the PREVIOUS step, as this did, landed them on
  // the map regardless of which field was actually missing.
  const gapStep = gaps.some(gap => gap !== "Service area") ? 2 : 3

  const setImage = (slot, dataUrl) =>
    update({ images: { ...draft.images, [slot]: dataUrl } })

  const clearImage = slot => {
    const nextImages = { ...draft.images }
    delete nextImages[slot]
    update({ images: nextImages })
  }

  return (
    <div>
      <h1 className={s.question}>Here is your website</h1>
      <p className={s.hint}>
        Built from your answers. Change the colours, swap in your own photographs, then put it
        online.
      </p>

      <div className={s.studio}>
        <div className={s.studioSide}>
          {/* Same segmented control as the Desktop / Phone switch, because it
              does the same kind of thing: it changes what the preview shows,
              not what has been bought. */}
          <div className={s.planTabs} role="tablist" aria-label="Plan">
            {TIER_ORDER.map(id => (
              <button
                key={id}
                type="button"
                role="tab"
                aria-selected={plan === id}
                className={`${s.planTab} ${plan === id ? s.planTabOn : ""}`}
                onClick={() => chooseTier(id)}
              >
                <span className={s.planName}>{PLANS[id].name}</span>
                <span className={s.planPrice}>
                  {/* Not "Free" again — the tab is already called that, and a
                      label that repeats its own name reads as a mistake. */}
                  {PLANS[id].amount === 0
                    ? "No charge"
                    : `${formatMoney(PLANS[id].amount, PLANS[id].currency)}/mo`}
                </span>
              </button>
            ))}
          </div>

          <div className={s.premiumBlock}>
            <p className={s.premiumTitle}>What you get</p>
            <PlanBenefits tier={plan} checked={benefits} onChange={setPlan} />
          </div>

          {plan !== "free" ? (
            <div className={s.premiumBlock}>
              <p className={s.premiumTitle}>Your page</p>
              <PremiumPanels draft={draft} update={update} onError={setError} />
            </div>
          ) : null}

          <div className={s.panel}>
            <p className={s.panelTitle}>Colour theme</p>
            <div className={s.themeGrid}>
              {THEMES.map(theme => (
                <button
                  key={theme.id}
                  type="button"
                  className={`${s.themeCard} ${draft.themeId === theme.id ? s.themeCardOn : ""}`}
                  onClick={() => update({ themeId: theme.id })}
                >
                  <span className={s.swatches}>
                    <span className={s.swatch} style={{ background: theme.primary }} />
                    <span className={s.swatch} style={{ background: theme.accent }} />
                    <span className={s.swatch} style={{ background: theme.ink }} />
                  </span>
                  <span className={s.themeName}>{theme.label}</span>
                  <span className={s.themeBlurb}>{theme.blurb}</span>
                </button>
              ))}
            </div>
          </div>

          <div className={s.panel}>
            <p className={s.panelTitle}>Pictures</p>
            <div className={s.slotList}>
              {IMAGE_SLOTS.map(slot => {
                const src = draft.images[slot.id]
                return (
                  <div key={slot.id} className={s.slotRow}>
                    {src ? (
                      <img src={src} alt="" className={s.slotThumb} />
                    ) : (
                      <span className={s.slotThumb} />
                    )}
                    <span>{slot.label}</span>
                    <span className={s.slotActions}>
                      <button
                        type="button"
                        className={s.linkBtn}
                        onClick={() => setPicking(slot.id)}
                      >
                        {src ? "Change" : "Add"}
                      </button>
                      {src ? (
                        <button type="button" className={s.linkBtn} onClick={() => clearImage(slot.id)}>
                          Remove
                        </button>
                      ) : null}
                    </span>
                  </div>
                )
              })}
            </div>
            <p className={s.fieldNote}>
              Click any picture in the preview to change it. Empty slots show a branded panel —
              never a stock photograph chosen for you, because somebody else&rsquo;s roof
              published as your work is a claim about your portfolio, not a placeholder.
            </p>
            {error ? <p className={s.error}>{error}</p> : null}
          </div>

          {gaps.length > 0 && (
            <div className={s.panel}>
              <div className={s.gaps}>
                <strong>Still to add</strong>
                {gaps.join(" · ")}
              </div>
              <button
                type="button"
                className={s.linkBtn}
                style={{ marginTop: 12 }}
                onClick={() => goTo(gapStep)}
              >
                Go back and fill these in
              </button>
            </div>
          )}
        </div>

        <div
          className={`${s.studioMain} ${device === "mobile" ? s.studioMainPhone : ""}`}
          style={{ "--canvas": `${CANVAS[device]}px` }}
        >
          {/* Everything that changes the SHAPE of the preview sits directly
              above the preview — MTC-FCS-023. The template chooser used to be
              a card down the side among the section switches, where it read as
              one more setting; the point of it is pressing an arrow and
              watching the page change. The device switch went one step further
              and is now inside the mock browser itself — MTC-FCS-024. */}
          {plan !== "free" ? (
            <div className={s.previewBar}>
              <TemplatePicker
                inline
                value={draft.templateId}
                onChange={templateId => update({ templateId })}
              />
            </div>
          ) : null}

          <DevicePreview
            draft={draft}
            device={device}
            onDevice={setDevice}
            onPickSlot={setPicking}
            /* So the design can be changed from full screen, where it is
               actually being judged — MTC-FCS-052. */
            onTemplate={templateId => update({ templateId })}
            plan={draft.plan}
          />
        </div>
      </div>

      {/* Three controls became two — MTC-FCS-025. "Change my answers" is gone
          (the step trail at the top of the page goes anywhere, and did before
          this button existed), and the price panel and the download link are
          one button instead of two things sitting next to each other. The
          price did not disappear with the panel: it is in the sentence, where
          it is read rather than glanced at. */}
      {picking ? (
        <ImagePicker
          slot={picking}
          label={(IMAGE_SLOTS.find(sl => sl.id === picking) || {}).label || "Picture"}
          current={draft.images[picking]}
          onChoose={dataUrl => setImage(picking, dataUrl)}
          onClear={() => clearImage(picking)}
          onClose={() => setPicking(null)}
        />
      ) : null}

      <div className={s.goLive}>
        <span className={s.goLiveCopy}>
          <strong>Happy with it?</strong>
          <span>
            {chosenPlan.amount === 0
              ? "Download the page and host it anywhere, or put it online on your own subdomain."
              : `Put it online on your own subdomain for ${formatMoney(
                  chosenPlan.amount,
                  chosenPlan.currency
                )}/${chosenPlan.interval} — cancel any time.`}
          </span>
        </span>

        {/* The download is always the free version, whatever tier is selected
            — see downloadSite() in lib/site-export.js. The button says so,
            because a file that quietly comes out different from the preview
            beside it is the kind of surprise people find later. */}
        <button type="button" className={s.goLiveGhost} onClick={() => downloadSite(draft)}>
          <strong>Download Page</strong>
          <span>Free version</span>
        </button>

        <button type="button" className="btn btn--lg" onClick={next}>
          Go live now
          <ArrowRight className="btn__arrow" />
        </button>
      </div>
    </div>
  )
}

export default StepCustomise
