import * as React from "react"
import { renderSiteDocument, collectSiteCss } from "../../lib/site-export"
import { ExpandIcon, MobileIcon, MonitorIcon } from "../Icons"
import TemplatePicker from "./TemplatePicker"
import PriceToast from "./PriceToast"
import * as s from "./DevicePreview.module.css"

/**
 * Desktop and phone previews of the generated site.
 *
 * ── IT IS AN IFRAME, AND THAT IS THE POINT ─────────────────────────────────
 * The site is responsive, so "what does it look like on a phone" is a question
 * about the VIEWPORT, and `@media (max-width: 640px)` does not care how narrow
 * a div is — only how wide the window is. Rendering into an iframe at 390px
 * makes the real breakpoints fire, so the phone tab shows the phone layout
 * rather than a squashed desktop.
 *
 * The iframe is also what makes this honest: it is handed the exact document
 * the download and the publish produce, so the preview cannot drift from the
 * thing that ships. If the export is broken, this looks broken.
 *
 * ── THE DEVICE SWITCH LIVES IN THE MOCK BROWSER — MTC-FCS-024 ──────────────
 * In the chrome bar, where a browser's own controls are. It is a control that
 * only means anything in relation to this frame, and putting it on the frame
 * says that without a label: the pair reads as one object rather than as a
 * setting that happens to sit above a picture.
 *
 * ── THE PICTURES ARE CLICKABLE IN PLACE — MTC-FCS-027 ──────────────────────
 * `allow-same-origin` (which the height measurement already needs) means the
 * parent can listen inside the frame. A click on a `data-slot` element opens
 * the picker for that picture, so somebody changes a photograph by pointing at
 * the photograph rather than by finding its row in a list down the side.
 *
 * The cursor and outline that say "this is clickable" are INJECTED into the
 * frame from here, never written into the document itself: the same document
 * is what gets downloaded and published, and a published site must not carry
 * the builder's editing affordances.
 *
 * ── AND A WAY TO SEE IT FOR REAL — MTC-FCS-025 ─────────────────────────────
 * The frame is a scaled-down picture in a column beside a form. "Full screen"
 * opens the same document at the size somebody's customers will actually meet
 * it — no transform, no column, no chrome. It is the same `srcDoc`, so it
 * cannot drift from the preview or from what gets published.
 *
 * ── SCALED TO FIT, MEASURED TO FIT ─────────────────────────────────────────
 * The frame renders at full device width and is scaled down with a transform.
 * A transformed element still occupies its untransformed size, so the scaled
 * height is measured back out of the document and applied to the wrapper —
 * without it the preview reserves thousands of pixels of blank page.
 */

/* Exported because the studio column sizes itself from the same number — two
   places deciding how wide a phone is would drift the moment one changed. */
export const CANVAS = { desktop: 1280, mobile: 390 }

const DevicePreview = ({ draft, device, onDevice, onPickSlot, onTemplate, plan }) => {
  const outer = React.useRef(null)
  const frame = React.useRef(null)
  const [scale, setScale] = React.useState(1)
  const [height, setHeight] = React.useState(520)
  const [doc, setDoc] = React.useState("")
  const [full, setFull] = React.useState(false)

  // Rendering to a string on every keystroke would be wasteful; the draft is
  // the only input, so it is the only trigger.
  React.useEffect(() => {
    // The CSS has to be read off the live page, so this can only run in the
    // browser — during SSR the iframe is simply empty.
    if (typeof document === "undefined") return
    setDoc(renderSiteDocument(draft, collectSiteCss()))
  }, [draft])

  const fit = React.useCallback(() => {
    const box = outer.current
    const el = frame.current
    if (!box || !el) return
    const next = Math.min(1, box.clientWidth / CANVAS[device])
    setScale(next)
    try {
      const inner = el.contentDocument
      if (inner && inner.body) {
        /* ── MEASURE WITH THE FRAME COLLAPSED — MTC-FCS-022 ──────────────
           `documentElement.scrollHeight` is never less than the VIEWPORT,
           and the viewport here is the height we ourselves just set. So
           measuring while the frame is tall only ever confirms that it is
           tall: the number ratchets up and never comes back down. Switching
           off a premium section, or from a long template to a short one, left
           the site sitting above a screen of empty white.

           Collapsing to 0 first makes the viewport too small to influence the
           answer, so what comes back is the content's own height. It costs two
           forced layouts per measurement, a handful of times per edit. */
        const before = el.style.height
        el.style.height = "0px"
        const h = Math.max(inner.body.scrollHeight, inner.documentElement.scrollHeight)
        el.style.height = before
        if (h > 0) setHeight(h)
      }
    } catch {
      /* Same-origin srcDoc should always be readable; if it is not, the last
         known height is better than collapsing the frame to nothing. */
    }
  }, [device])

  /* ── Clicking a picture inside the frame — MTC-FCS-027 ──────────────── */
  const pickRef = React.useRef(onPickSlot)
  pickRef.current = onPickSlot

  React.useEffect(() => {
    if (!onPickSlot) return undefined
    const el = frame.current
    if (!el) return undefined

    let inner = null

    const attach = () => {
      inner = el.contentDocument
      if (!inner || !inner.body) return

      // Injected, not authored into the document: see the note at the top.
      const style = inner.createElement("style")
      style.setAttribute("data-builder-chrome", "")
      style.textContent = `
        [data-slot]{cursor:pointer}
        /* ZERO SPECIFICITY ON PURPOSE — MTC-FCS-041.
           The label below is centred on the picture, which needs the picture
           to be a containing block. Forcing position:relative on every slot
           did that — and knocked every full-bleed photograph out of place,
           because a hero image is absolutely positioned at inset 0, and
           relative puts it back in the flow: the hero lost its background and
           the copy under it was pushed down. Only the preview injects this, so
           only the preview was wrong and full screen looked right.
           :where() scores zero, so a design's own position always wins and
           this only reaches slots that had none. An absolutely positioned slot
           is already a containing block, so the label still centres on it. */
        :where([data-slot]){position:relative}
        [data-slot]:hover{outline:3px solid #1668e8;outline-offset:-3px}
        [data-slot]:hover::after{
          content:"Change picture";position:absolute;left:50%;top:50%;
          transform:translate(-50%,-50%);z-index:5;
          padding:7px 14px;border-radius:999px;
          background:rgba(13,23,38,.86);color:#fff;
          font:600 13px/1 "Inter Variable",Inter,system-ui,sans-serif;
          white-space:nowrap;pointer-events:none}
      `
      inner.head.appendChild(style)

      inner.addEventListener("click", onClick, true)
    }

    /** The nearest thing that actually scrolls, walking out of the frame. */
    const scrollerFor = node => {
      let current = node
      while (current && current !== document.body) {
        const style = window.getComputedStyle(current)
        if (
          /(auto|scroll)/.test(style.overflowY) &&
          current.scrollHeight > current.clientHeight + 4
        ) {
          return current
        }
        current = current.parentElement
      }
      return null
    }

    const onClick = event => {
      /* ── The preview's own navigation — MTC-FCS-042 ──────────────────
         An anchor inside the frame cannot scroll it: the iframe is sized to
         its full content, so there is no overflow to move. The jump has to
         happen out here, in whatever is actually scrolling — the page
         normally, the overlay in full screen. */
      const link =
        event.target && event.target.closest ? event.target.closest('a[href^="#"]') : null
      if (link) {
        const id = (link.getAttribute("href") || "").slice(1)
        const destination = id ? inner.getElementById(id) : null
        event.preventDefault()
        if (!destination) return

        const frame = el.getBoundingClientRect()
        // The phone view draws the frame at a smaller scale than the document
        // it contains, so a position inside the document is not a position on
        // the screen until it is scaled.
        const scale = frame.height / (inner.documentElement.scrollHeight || frame.height)
        const offset = destination.getBoundingClientRect().top * scale

        const scroller = scrollerFor(el)
        if (scroller) {
          scroller.scrollTo({
            top: scroller.scrollTop + (frame.top - scroller.getBoundingClientRect().top) + offset - 16,
            behavior: "smooth",
          })
        } else {
          window.scrollTo({ top: window.scrollY + frame.top + offset - 16, behavior: "smooth" })
        }
        return
      }

      const target = event.target && event.target.closest
        ? event.target.closest("[data-slot]")
        : null
      if (!target) return
      // The preview's links are real; a click meant for a picture must not
      // also follow the anchor it happens to sit inside.
      event.preventDefault()
      event.stopPropagation()
      const id = target.getAttribute("data-slot")
      if (id && pickRef.current) pickRef.current(id)
    }

    attach()
    el.addEventListener("load", attach)

    return () => {
      el.removeEventListener("load", attach)
      if (inner) {
        inner.removeEventListener("click", onClick, true)
        const style = inner.querySelector("style[data-builder-chrome]")
        if (style) style.remove()
      }
    }
  }, [doc, device, onPickSlot])

  React.useEffect(() => {
    if (!full) return undefined
    const onKey = e => {
      if (e.key === "Escape") setFull(false)
    }
    // The page behind a full-screen overlay must not scroll: on a phone the
    // overlay stays put and the page slides around underneath it.
    const previous = document.body.style.overflow
    document.body.style.overflow = "hidden"
    window.addEventListener("keydown", onKey)
    return () => {
      document.body.style.overflow = previous
      window.removeEventListener("keydown", onKey)
    }
  }, [full])

  React.useEffect(() => {
    fit()
    const box = outer.current
    if (!box) return undefined

    const ro = new ResizeObserver(fit)
    ro.observe(box)

    // Web fonts and decoded images land after `load`, and both change the
    // height. A couple of follow-up measurements are cheaper and far more
    // reliable than trying to await everything inside the frame.
    const settle = [setTimeout(fit, 250), setTimeout(fit, 900)]

    return () => {
      ro.disconnect()
      settle.forEach(clearTimeout)
    }
  }, [fit, doc, device])

  return (
    <div
      className={`${s.frame} ${device === "mobile" ? s.phone : s.laptop}`}
      // The frame is sized from the same number the canvas is, so the two can
      // never disagree and leave a gap between them.
      style={{ "--canvas": `${CANVAS[device]}px` }}
    >
      <div className={s.chrome}>
        <span className={s.dot} />
        <span className={s.dot} />
        <span className={s.dot} />
        <span className={s.url}>
          {(draft.business.name.trim() || "yourbusiness")
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, "-")
            .replace(/^-|-$/g, "") || "yourbusiness"}
          .freecontractorservices.com
        </span>

        {/* Icons, not words — MTC-FCS-018. The label moves to aria-label
            rather than disappearing: a control that is only a picture still
            has to answer "what is this?" for anyone not looking at it. */}
        {onDevice ? (
          <div className={s.deviceTabs} role="tablist" aria-label="Preview size">
            {[
              { id: "desktop", label: "Desktop", Icon: MonitorIcon },
              { id: "mobile", label: "Phone", Icon: MobileIcon },
            ].map(tab => (
              <button
                key={tab.id}
                type="button"
                role="tab"
                aria-selected={device === tab.id}
                aria-label={`${tab.label} preview`}
                title={`${tab.label} preview`}
                className={`${s.deviceTab} ${device === tab.id ? s.deviceTabOn : ""}`}
                onClick={() => onDevice(tab.id)}
              >
                <tab.Icon />
              </button>
            ))}
          </div>
        ) : null}

        {/* Same document, no transform, no column — MTC-FCS-025. */}
        <button
          type="button"
          className={s.expand}
          aria-label="Open a full screen preview"
          title="Full screen"
          onClick={() => setFull(true)}
        >
          <ExpandIcon />
        </button>
      </div>

      <div className={s.viewport} ref={outer} style={{ height: `${height * scale}px` }}>
        <iframe
          ref={frame}
          title="Website preview"
          className={s.canvas}
          srcDoc={doc}
          onLoad={fit}
          // allow-same-origin WITHOUT allow-scripts: the frame's height has to
          // be measured through contentDocument, which an opaque origin
          // forbids, while leaving scripts off means nothing inside can run.
          // The published file ships no JavaScript either.
          sandbox="allow-same-origin"
          style={{
            width: `${CANVAS[device]}px`,
            height: `${height}px`,
            transform: `scale(${scale})`,
          }}
        />
      </div>

      {/* The overlay renders the SAME srcDoc, so it cannot drift from the
          preview or from what gets published — there is one document. */}
      {full ? (
        <div
          className={s.fullWrap}
          role="dialog"
          aria-modal="true"
          aria-label="Full screen preview"
        >
          <div className={s.fullBar}>
            <span className={s.fullTitle}>
              {device === "mobile" ? "Phone" : "Desktop"} preview
            </span>

            {/* ── CHANGING DESIGN WITHOUT LEAVING — MTC-FCS-052 ───────────
                The same picker as the studio column, not a second one: this
                is where somebody actually judges a design, and closing the
                preview to change it and reopening it to look meant nobody
                compared anything. `onTemplate` missing simply leaves the bar
                as it was, so a caller that has no template to change still
                gets a working full screen. */}
            {onTemplate ? (
              <div className={s.fullPicker}>
                <TemplatePicker inline value={draft.templateId} onChange={onTemplate} />
              </div>
            ) : null}

            <button type="button" className={s.fullClose} onClick={() => setFull(false)}>
              Close
            </button>
          </div>
          {/* Slides up on the way in and again on every change of design —
              MTC-FCS-052. */}
          <PriceToast templateId={draft.templateId} plan={plan || draft.plan} />

          <iframe
            title="Full screen website preview"
            className={s.fullFrame}
            srcDoc={doc}
            sandbox="allow-same-origin"
            style={
              device === "mobile"
                ? { width: `${CANVAS.mobile}px`, maxWidth: "100%" }
                : undefined
            }
          />
        </div>
      ) : null}
    </div>
  )
}

export default DevicePreview
