import * as React from "react"
import { formatPhone, formatPhoneInput } from "../lib/phone"

/**
 * A phone field that formats itself — MTC-FCS-011.
 * ============================================================================
 * One component for both forms that collect a number, so the builder and the
 * invoice cannot drift apart on what a phone number looks like.
 *
 * ── IT ONLY REFORMATS WHEN THE CARET IS AT THE END ─────────────────────────
 * Rewriting the value on every keystroke moves the caret, because the string
 * the person is editing is not the string that comes back. While they are
 * typing or backspacing at the end that is invisible and useful; in the middle
 * of a number it throws them to the end mid-edit, which is the thing everybody
 * hates about phone fields. So mid-string edits are left completely alone and
 * tidied on blur instead.
 *
 * ── IT DOES NOT VALIDATE ───────────────────────────────────────────────────
 * Nothing here refuses input. A field that rejects what somebody typed has to
 * be right about every number in the world, and this one only claims to know
 * about North America. See `src/lib/phone.js`.
 */
const PhoneInput = ({ value, onChange, ...rest }) => {
  const ref = React.useRef(null)
  const toEnd = React.useRef(false)

  // Putting the caret back has to happen after React has painted the new
  // value, or it is immediately overwritten by the old selection.
  React.useEffect(() => {
    if (!toEnd.current) return
    toEnd.current = false
    const el = ref.current
    if (el && document.activeElement === el) {
      el.setSelectionRange(el.value.length, el.value.length)
    }
  }, [value])

  const handleChange = e => {
    const el = e.target
    const atEnd = el.selectionStart === el.value.length
    if (!atEnd) {
      onChange(el.value)
      return
    }
    const next = formatPhoneInput(el.value)
    toEnd.current = next !== el.value
    onChange(next)
  }

  return (
    <input
      ref={ref}
      type="tel"
      inputMode="tel"
      autoComplete="tel"
      value={value}
      onChange={handleChange}
      onBlur={e => {
        const tidied = formatPhone(e.target.value)
        if (tidied !== e.target.value) onChange(tidied)
      }}
      {...rest}
    />
  )
}

export default PhoneInput
