import { withPrefix } from "gatsby"

/**
 * Loading the county geography, one state at a time.
 *
 * Ported from contractor.wiki. The national county dataset is one file, but
 * nobody needs all of it: a contractor in Boise is asked which Idaho counties
 * they serve, so the browser fetches Idaho — 20-odd KB — and never learns the
 * shape of Alaska.
 *
 * These are plain files under `static/maps/`, so this is the browser
 * downloading an asset exactly like an image. No map API, no key, no request
 * fee, nothing to rate-limit. The geometry is US Census cartographic boundary
 * data, generalised for mapping.
 *
 * The PROMISE is cached rather than the result, so switching between two
 * states repeatedly issues one request each and in-flight requests are shared.
 * A rejected load is evicted so a dropped connection can be retried, rather
 * than being remembered forever as "this state is broken".
 */

const cache = new Map()

export function loadCounties(usps) {
  const code = String(usps || "").toUpperCase()
  const hit = cache.get(code)
  if (hit) return hit

  const request = fetch(withPrefix(`/maps/counties/${code}.json`))
    .then(async res => {
      if (!res.ok) throw new Error(`Counties for ${code} unavailable (HTTP ${res.status})`)
      const data = await res.json()
      if (!data || !Array.isArray(data.features)) {
        throw new Error(`Counties for ${code} were not valid GeoJSON`)
      }
      return data
    })
    .catch(err => {
      cache.delete(code)
      throw err
    })

  cache.set(code, request)
  return request
}

/** Alphabetical — the list beside the map is read, not scanned by shape. */
export function sortedCounties(data) {
  if (!data) return []
  return data.features
    .map(f => f.properties)
    .sort((a, b) => a.NAMELSAD.localeCompare(b.NAMELSAD))
}

/* ── Working across state lines — MTC-FCS-026 ──────────────────────────── */

/**
 * GEOID -> county name, filled in as each state's file arrives.
 *
 * A draft stores GEOIDs — five characters instead of a polygon, which is the
 * whole point of storing an identifier — but "04001" means nothing on screen.
 * The names live in files that may not be loaded yet, so this is the index
 * that lets a county selected in one state be labelled while another state's
 * list is open.
 */
const nameIndex = new Map()

export function rememberNames(data) {
  if (!data) return
  for (const feature of data.features) {
    nameIndex.set(feature.properties.GEOID, feature.properties.NAMELSAD)
  }
}

/**
 * The name for a GEOID, or the GEOID itself.
 *
 * Never a guess: an id whose state has not been loaded comes back as the id,
 * which looks wrong on screen, which is the correct outcome — it says "this
 * has not loaded" rather than inventing a county.
 */
export function countyName(geoid) {
  return nameIndex.get(geoid) || geoid
}

/** Names for a list of GEOIDs, in the order given. */
export function countyNames(geoids) {
  return (geoids || []).map(countyName)
}

/**
 * Counties for several states at once, as one collection.
 *
 * ── WHY THE MAP NEEDS MORE THAN ONE STATE ──────────────────────────────────
 * A roofer in Coeur d'Alene works in Idaho and eastern Washington; a plumber
 * in Delaware crosses three states before lunch. One state at a time means the
 * county on the far side of the line — often the nearest work there is — is
 * simply not on the map.
 *
 * Loading everything is not the alternative: 3,144 counties is over a megabyte
 * and more Leaflet paths than a laptop enjoys. Only the states in play are
 * fetched, which is usually two or three.
 *
 * ── ONE BAD FILE DOES NOT BLANK THE MAP ────────────────────────────────────
 * A state that fails to load is reported and left out, rather than rejecting
 * the whole set. The rest of somebody's service area is still worth drawing.
 */
export async function loadCountiesFor(codes) {
  const unique = [...new Set((codes || []).map(c => String(c || "").toUpperCase()))].filter(Boolean)
  const results = await Promise.allSettled(unique.map(code => loadCounties(code)))

  const features = []
  const failed = []

  results.forEach((result, index) => {
    if (result.status === "fulfilled") {
      rememberNames(result.value)
      rememberFips(unique[index], result.value)
      features.push(...result.value.features)
    } else {
      failed.push(unique[index])
    }
  })

  return { collection: { type: "FeatureCollection", features }, failed }
}

/**
 * Which states a set of GEOIDs belongs to, as two-digit FIPS codes.
 *
 * A county GEOID is the state FIPS followed by the county code, so the state
 * is the first two characters and nothing has to be looked up.
 */
export function statesInSelection(geoids) {
  return [...new Set((geoids || []).map(id => String(id).slice(0, 2)).filter(p => p.length === 2))]
}

/** The features belonging to one state, by its FIPS code. */
export function featuresForState(data, statefp) {
  if (!data) return []
  return data.features.filter(f => f.properties.STATEFP === statefp)
}

/**
 * USPS code -> FIPS, learned from the files rather than from a table.
 *
 * The geometry already carries STATEFP, so a second hard-coded mapping would
 * only be a chance for the two to disagree.
 */
const fipsByCode = new Map()

export function rememberFips(usps, data) {
  const first = data && data.features && data.features[0]
  if (first) fipsByCode.set(String(usps).toUpperCase(), first.properties.STATEFP)
}

export function fipsFor(usps) {
  return fipsByCode.get(String(usps || "").toUpperCase()) || null
}
